begin;
select plan(12);
select ok(not has_table_privilege('anon','public.payment_orders','select,insert,update,delete'),'anonymous clients cannot access payment orders');
select ok(not has_table_privilege('authenticated','public.payment_orders','select,insert,update,delete'),'authenticated clients cannot bypass payment ownership');
select ok(not has_table_privilege('anon','public.payment_refunds','select,insert,update,delete'),'refunds are server only');
select ok(not has_function_privilege('authenticated','public.payment_apply_event(text,text,text,text,text)','execute'),'clients cannot mark orders paid');
select is((select count(*)::integer from pg_class where relname in ('payment_orders','payment_events','payment_refunds') and relrowsecurity),3,'all payment tables use RLS');
select public.payment_create_order('test-order','owner','app','1.00','key');
select is(public.payment_create_order('ignored-order','owner','app','1.00','key')->>'out_trade_no','test-order','checkout retries return the same order');
select public.payment_apply_event('test-order','trade','PAID','notify-one','payment');
select public.payment_apply_event('test-order','trade','PAID','notify-one','payment');
select is((select count(*)::integer from public.payment_events where out_trade_no='test-order'),1,'notifications are persisted once');
select public.payment_apply_event('test-order','trade','CLOSED','notify-two','non_payment');
select is((select state from public.payment_orders where out_trade_no='test-order'),'PAID','late non-payment events cannot downgrade a paid order');
select public.payment_reserve_refund('test-order','refund-one','0.60','reason');
select is(public.payment_reserve_refund('test-order','refund-one','0.60','reason')->>'amount','0.60','same refund retry reuses its reservation');
select throws_ok($$select public.payment_reserve_refund('test-order','refund-one','0.50','reason')$$,'P0001','PAYMENT_REFUND_CONFLICT','refund retry rejects changed parameters');
select throws_ok($$select public.payment_reserve_refund('test-order','refund-two','0.50','reason')$$,'P0001','PAYMENT_REFUND_EXCEEDS_PAID','pending refunds count toward the limit');
select throws_ok($$select public.payment_apply_event('test-order','other-trade','PAID','notify-three','payment')$$,'P0001','PAYMENT_TRADE_MISMATCH','an order cannot switch its Alipay transaction');
select * from finish();
rollback;
